select 'framework_items_all_present' as check_name,
  (select count(*) from public.compliance_items where name in ($q$Building Warrant of Fitness$q$,$q$Fire alarms — tested and detection confirmed working$q$,$q$Marae decision recorded: how safety measures are applied in the wharenui and tapu spaces$q$,$q$Marae decision recorded: role as an emergency hub and who decides when it opens$q$,$q$Written evacuation procedure for each building the public is admitted to$q$,$q$As an employer: duty to keep workers and others safe confirmed with WorkSafe$q$,$q$As an employer: trustees checked whether the officer due diligence duty applies$q$,$q$Health & Safety Policy Review$q$,$q$Recorded whether the marae employs anyone on an employment agreement$q$,$q$Volunteer safety induction done; incident and near-miss register kept$q$,$q$Building & Contents Insurance$q$,$q$Public Liability Insurance$q$,$q$Changes notified to Charities Services within 3 months (name, address, balance date, rules, purposes, officers)$q$,$q$Charities annual return and performance report filed within 6 months of balance date$q$,$q$Governance procedures reviewed in the last 3 years$q$,$q$Trustee records backed up and a restore tested$q$,$q$Accurate, separate, up-to-date records of the reservation's administration kept$q$,$q$Annual meeting held with at least 21 days' notice, open to beneficiaries$q$,$q$Conflicts of interest register kept and on the meeting agenda$q$,$q$Current list of trustees with appointment and term end dates$q$,$q$First trustee meeting within 30 days of appointment; minute book kept$q$,$q$Marae charter — written with beneficiaries; signed copy located (good practice)$q$,$q$Notice of each trustee appointment published in a local newspaper within 7 days$q$,$q$Reservation money in a separate bank account with at least two authorised signatories$q$,$q$Succession plan for trustees and key volunteers agreed$q$,$q$Trustees know the terms of the trust and their five mandatory duties$q$,$q$Trustees know their duty to act in good faith and run the reservation for its purposes$q$,$q$Water assessment recorded: source, who is supplied, how many people$q$)) = 28 as result
union all
select 'no_duplicate_item_names',
  (select count(*) from (select name from public.compliance_items group by name having count(*) > 1) d) = 0
union all
select 'conflicts_register_stays_to_verify',
  (select legal_basis_detail from public.compliance_items where name like 'Conflicts of interest register%') like 'NOT YET VERIFIED%';
